    org_webdavConfig:       { de: 'WebDAV-Publish (Nextcloud/ownCloud)',  en: 'WebDAV Publish (Nextcloud/ownCloud)',   fr: 'Publication WebDAV (Nextcloud/ownCloud)', nl: 'WebDAV-publicatie (Nextcloud/ownCloud)' },
    org_webdavDesc:         { de: 'Freigegebene Richtlinien werden als PDF in einen Nextcloud/ownCloud-Ordner hochgeladen. Ein Ausfall des Remote-Systems beeinflusst die Freigabe nie — die Richtlinie bleibt freigegeben, der Fehler ist hier sichtbar und lässt sich per Re-Sync wiederholen. Weitere Sichtbarkeits-Optionen (Favorit-Markierung, öffentlicher Link) lassen sich per .env aktivieren, siehe .env.example.', en: 'Approved policies are uploaded as PDF to a Nextcloud/ownCloud folder. A failure of the remote system never affects the approval — the policy stays approved, the error is visible here and can be retried via re-sync. Further visibility options (favorite marking, public link) can be enabled via .env, see .env.example.', fr: 'Les politiques approuvées sont téléchargées au format PDF dans un dossier Nextcloud/ownCloud. Une panne du système distant n’affecte jamais l’approbation — la politique reste approuvée, l’erreur est visible ici et peut être relancée via une resynchronisation. D’autres options de visibilité (marquage favori, lien public) peuvent être activées via .env, voir .env.example.', nl: 'Goedgekeurd beleid wordt als PDF geüpload naar een Nextcloud/ownCloud-map. Een storing van het externe systeem heeft nooit invloed op de goedkeuring — het beleid blijft goedgekeurd, de fout is hier zichtbaar en kan opnieuw worden geprobeerd via re-sync. Extra zichtbaarheidsopties (favoriet markeren, openbare link) kunnen via .env worden ingeschakeld, zie .env.example.' },
    org_webdavEnable:       { de: 'Automatischen Publish bei Freigabe aktivieren', en: 'Enable auto-publish on approval', fr: 'Activer la publication automatique lors de l’approbation', nl: 'Automatisch publiceren bij goedkeuring inschakelen' },
    org_webdavEnableDesc:   { de: 'Bei jeder Freigabe eines Dokuments wird automatisch hochgeladen. Manueller Re-Sync ist im Dokumenten-Editor immer möglich.', en: 'Every time a document is approved, it is uploaded automatically. Manual re-sync is always available in the document editor.', fr: 'À chaque approbation d’un document, le téléchargement se fait automatiquement. La resynchronisation manuelle est toujours possible dans l’éditeur de documents.', nl: 'Bij elke goedkeuring van een document wordt automatisch geüpload. Handmatige re-sync is altijd mogelijk in de documenteditor.' },
    org_webdavBaseUrl:      { de: 'Basis-URL',                 en: 'Base URL',                  fr: 'URL de base',                nl: 'Basis-URL' },
    org_webdavUsername:     { de: 'Benutzername',              en: 'Username',                  fr: 'Nom d’utilisateur',          nl: 'Gebruikersnaam' },
    org_webdavAppPassword:  { de: 'App-Passwort',               en: 'App password',              fr: 'Mot de passe d’application',  nl: 'App-wachtwoord' },
    org_webdavAppPasswordNotice: { de: 'Bitte ein App-Passwort verwenden (Nextcloud: Einstellungen → Sicherheit → Neues App-Passwort erzeugen), nicht das Hauptkonto-Passwort. App-Passwörter sind einzeln widerrufbar und begrenzen den Schaden, falls dieser Wert kompromittiert wird.', en: 'Please use an app password (Nextcloud: Settings → Security → create new app password), not the main account password. App passwords are individually revocable and limit the damage if this value is compromised.', fr: 'Veuillez utiliser un mot de passe d’application (Nextcloud : Paramètres → Sécurité → créer un nouveau mot de passe d’application), pas le mot de passe du compte principal. Les mots de passe d’application sont révocables individuellement et limitent les dégâts en cas de compromission.', nl: 'Gebruik een app-wachtwoord (Nextcloud: Instellingen → Beveiliging → nieuw app-wachtwoord aanmaken), niet het hoofdaccountwachtwoord. App-wachtwoorden zijn afzonderlijk intrekbaar en beperken de schade als deze waarde wordt gecompromitteerd.' },
